window.VO = [{"id":"n01","text":"You're the cashier, and he's got a knife.","at":0.24,"t0":0.12,"t1":3.029},{"id":"r01","text":"Open the drawer!","at":6.558,"t0":3.279,"t1":4.37},{"id":"n02","text":"Now pick him.","at":11.74,"t0":5.87,"t1":6.961},{"id":"n03","text":"Whoever you pick goes to jail.","at":14.322,"t0":7.161,"t1":9.343},{"id":"n04","text":"Now pick his knife.","at":24.286,"t0":12.143,"t1":13.598},{"id":"n05","text":"You'd know that knife anywhere.","at":31.194,"t0":15.597,"t1":17.415},{"id":"n06","text":"But the knife doesn't go to jail.","at":35.53,"t0":17.765,"t1":20.31},{"id":"n07","text":"Were you that sure of the man you sent to jail?","at":41.822,"t0":20.911,"t1":24.911},{"id":"n08","text":"His face was right there.","at":50.822,"t0":25.411,"t1":27.229},{"id":"n09","text":"He's number two.","at":55.458,"t0":27.729,"t1":28.82},{"id":"n10","text":"Picked nobody? He's still out there.","at":58.64,"t0":29.32,"t1":31.502},{"id":"n11","text":"Picked one, three or four?","at":64.004,"t0":32.002,"t1":33.82},{"id":"n12","text":"You just sent an innocent man to jail.","at":68.84,"t0":34.42,"t1":37.329},{"id":"n13","text":"It's called weapon focus.","at":76.658,"t0":38.329,"t1":39.784},{"id":"n14","text":"In the classic test, one in three picked the right man.","at":80.168,"t0":40.084,"t1":44.084},{"id":"n14b","text":"With a gun, one in seven.","at":88.768,"t0":44.384,"t1":46.566},{"id":"n15","text":"Got number two?","at":94.73,"t0":47.365,"t1":48.456},{"id":"n16","text":"Then who else was in the shop?","at":97.712,"t0":48.856,"t1":51.401}];
